import { NextRequest, NextResponse } from "next/server";
import { Client } from "@hubspot/api-client";
import { COOKIE_NAME, REFRESH_TOKEN_COOKIE, EXPIRES_IN_COOKIE } from "@/lib/constants";
import { cookies } from "next/headers";

const hubspotClient = new Client();

export async function GET(request: NextRequest) {
    const searchParams = request.nextUrl.searchParams;
    const code = searchParams.get("code");

    if (!code) {
        return NextResponse.json({ error: "Code not found" }, { status: 400 });
    }

    try {
        const tokenResponse = await hubspotClient.oauth.tokensApi.create(
            "authorization_code",
            code,
            process.env.HUBSPOT_REDIRECT_URI,
            process.env.HUBSPOT_CLIENT_ID,
            process.env.HUBSPOT_CLIENT_SECRET
        );

        const { accessToken, refreshToken, expiresIn } = tokenResponse;

        const cookieStore = await cookies();

        // Set Access Token
        cookieStore.set(COOKIE_NAME, accessToken, {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            maxAge: expiresIn,
            path: "/",
        });

        // Set Refresh Token (Make it last longer, e.g., 30 days)
        cookieStore.set(REFRESH_TOKEN_COOKIE, refreshToken, {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            maxAge: 60 * 60 * 24 * 30, // 30 days
            path: "/",
        });

        // Set Expiration Time
        cookieStore.set(EXPIRES_IN_COOKIE, (Date.now() + expiresIn * 1000).toString(), {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            maxAge: expiresIn,
            path: "/",
        });

        return NextResponse.redirect(new URL("/dashboard", request.url));
    } catch (error: any) {
        console.error("Error exchanging code for token:", error);
        return NextResponse.json(
            { error: "Failed to exchange code for token", details: error.message },
            { status: 500 }
        );
    }
}

import { PropertyGrid } from "@/components/dashboard/property-grid";
import { AssociationsList } from "@/components/dashboard/associations-list";
import { getObject } from "@/lib/actions";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { ArrowLeft } from "lucide-react";

export default async function ObjectPage({
    params,
}: {
    params: Promise<{
        type: string;
        id: string;
    }>;
}) {
    const { type, id } = await params;

    try {
        const object = await getObject(type, id);
        const properties = object.properties;
        const associations = (object as any).associations;

        return (
            <div className="flex-1 space-y-4 p-8 pt-6">
                <div className="flex items-center space-x-2 mb-4">
                    <Button variant="ghost" size="sm" asChild>
                        <Link href={`/dashboard/${type}`}>
                            <ArrowLeft className="mr-2 h-4 w-4" />
                            Back to {type}
                        </Link>
                    </Button>
                </div>
                <div className="flex items-center justify-between space-y-2">
                    <h2 className="text-3xl font-bold tracking-tight capitalize">
                        {(() => {
                            const singularMap: Record<string, string> = {
                                contacts: "Contact",
                                companies: "Company",
                                deals: "Deal",
                                tickets: "Ticket",
                                products: "Product",
                                quotes: "Quote",
                                "line-items": "Line Item",
                            };
                            return singularMap[type] || type;
                        })()} Details
                    </h2>
                </div>
                <div className="grid gap-6 md:grid-cols-1 lg:grid-cols-3">
                    <Card className="col-span-2">
                        <CardHeader>
                            <CardTitle>Properties</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <PropertyGrid properties={properties} type={type} id={id} />
                        </CardContent>
                    </Card>

                    <div className="col-span-1">
                        <AssociationsList associations={associations} currentType={type} />
                    </div>
                </div>
            </div>
        );
    } catch (error: any) {
        return (
            <div className="p-8 text-red-500">
                <h2 className="text-xl font-bold mb-2">Error loading {type}</h2>
                <p>ID: {id}</p>
                <p className="mt-2">Details: {error.message}</p>
                <div className="mt-4">
                    <Button variant="outline" asChild>
                        <Link href={`/dashboard/${type}`}>Back to List</Link>
                    </Button>
                </div>
            </div>
        );
    }
}

import { getCompanies, getAllProperties } from "@/lib/actions";
