                                                </span>
                                            )}
                                            Archived: {item.archivedAt ? new Date(item.archivedAt).toLocaleString() : "Unknown"}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </ScrollArea>
                    )}
                </div>
            </SheetContent>
        </Sheet>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Pencil, Check, X, Loader2 } from "lucide-react";
import { updateObjectProperty } from "@/lib/actions/common";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";

interface EditPropertyProps {
    type: string;
    id: string;
    propertyKey: string;
    value: string | number | null | undefined;
    onCancel?: () => void;
    onSave?: () => void;
}

export function EditProperty({ type, id, propertyKey, value: initialValue, onCancel, onSave }: EditPropertyProps) {
    const [isEditing, setIsEditing] = useState(false);
    const [value, setValue] = useState(initialValue?.toString() || "");
    const [isLoading, setIsLoading] = useState(false);
    const { toast } = useToast();

    const handleSave = async () => {
        if (value === initialValue?.toString()) {
            setIsEditing(false);
            return;
        }

        setIsLoading(true);
        try {
            const result = await updateObjectProperty(type, id, propertyKey, value);
            if (result.success) {
                toast({
                    title: "Property updated",
                    description: `${propertyKey} has been updated successfully.`,
                });
                setIsEditing(false);
                if (onSave) onSave();
            } else {
                toast({
                    variant: "destructive",
                    title: "Update failed",
                    description: result.error || "Failed to update property.",
                });
            }
        } catch (error) {
            toast({
                variant: "destructive",
                title: "Update failed",
                description: "An unexpected error occurred.",
            });
        } finally {
            setIsLoading(false);
        }
    };

    const handleCancel = () => {
        setIsEditing(false);
        setValue(initialValue?.toString() || "");
        if (onCancel) onCancel();
    };

    if (isEditing) {
        return (
            <div className="flex items-center space-x-2 w-full">
                <Input
                    value={value}
                    onChange={(e) => setValue(e.target.value)}
                    className="h-8 text-sm"
                    autoFocus
                    onKeyDown={(e) => {
                        if (e.key === "Enter") handleSave();
                        if (e.key === "Escape") handleCancel();
                    }}
                    disabled={isLoading}
                />
                <Button
                    variant="ghost"
                    size="icon"
                    onClick={handleSave}
                    disabled={isLoading}
                    className="h-8 w-8 text-green-600 hover:text-green-700 hover:bg-green-50"
                >
                    {isLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                </Button>
                <Button
                    variant="ghost"
                    size="icon"
                    onClick={handleCancel}
                    disabled={isLoading}
                    className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50"
                >
                    <X className="h-4 w-4" />
                </Button>
            </div>
        );
    }

    return (
        <div className="group flex items-center justify-between w-full min-h-[2rem]">
            <span className="text-sm font-medium break-all">{initialValue?.toString()}</span>
            <Button
                variant="ghost"
                size="icon"
                onClick={() => {
                    setValue(initialValue?.toString() || "");
                    setIsEditing(true);
                }}
                className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity text-muted-foreground hover:text-foreground"
                title={`Edit ${propertyKey}`}
            >
                <Pencil className="h-3 w-3" />
            </Button>
        </div>
    );
}

"use client";

import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import Link from "next/link";
import { format } from "date-fns";
import { Badge } from "@/components/ui/badge";

interface Engagement {
    id: string;
    properties: {
        hs_engagement_type: string;
        hs_timestamp: string;
        hs_body_preview?: string;
        hs_task_subject?: string;
        hs_meeting_title?: string;
        hs_note_body?: string;
        [key: string]: any;
    };
}

interface EngagementsTableProps {
    data: Engagement[];
}

export function EngagementsTable({ data }: EngagementsTableProps) {
    if (!data || data.length === 0) {
        return <div className="p-4 text-muted-foreground">No engagements found.</div>;
    }

    const formatType = (type: string) => {
        return type ? type.replace(/_/g, " ").toLowerCase().replace(/\b\w/g, l => l.toUpperCase()) : "Unknown";
    };

    const getSubject = (props: any) => {
        if (props.hs_task_subject) return props.hs_task_subject;
        if (props.hs_meeting_title) return props.hs_meeting_title;
        if (props.hs_note_body) return props.hs_note_body.replace(/<[^>]*>?/gm, '').substring(0, 50) + "..."; // Strip HTML for notes
        if (props.hs_body_preview) return props.hs_body_preview;
        return "No Subject";
    };

    const getTypeColor = (type: string) => {
        switch (type) {
            case "EMAIL": return "default"; // dark
            case "CALL": return "secondary"; // gray
            case "MEETING": return "secondary"; // gray
            case "TASK": return "outline"; // white/border
            case "NOTE": return "outline";
            default: return "secondary";
        }
    };

    return (
        <Table>
            <TableHeader>
                <TableRow>
                    <TableHead>Activity Type</TableHead>
                    <TableHead>Subject / Body</TableHead>
                    <TableHead>Date</TableHead>
                </TableRow>
            </TableHeader>
            <TableBody>
                {data.map((item) => (
                    <TableRow key={item.id}>
                        <TableCell>
                            <Badge variant={getTypeColor(item.properties.hs_engagement_type) as "default" | "secondary" | "destructive" | "outline"}>
                                {formatType(item.properties.hs_engagement_type)}
                            </Badge>
                        </TableCell>
                        <TableCell className="font-medium">
                            <Link href={`/dashboard/engagements/${item.id}`} className="hover:underline">
                                {getSubject(item.properties)}
                            </Link>
                        </TableCell>
                        <TableCell>
                            {item.properties.hs_timestamp ? format(new Date(item.properties.hs_timestamp), "MMM d, yyyy h:mm a") : "-"}
                        </TableCell>
                    </TableRow>
                ))}
            </TableBody>
        </Table>
    );
}

"use client";

import { useState } from "react";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { PropertyItem } from "@/components/dashboard/property-item";

interface PropertyGridProps {
    properties: Record<string, any>;
    type: string;
    id: string;
}

export function PropertyGrid({ properties, type, id }: PropertyGridProps) {
    const [showAll, setShowAll] = useState(false);

    const visibleProperties = Object.entries(properties).filter(([key, value]) => {
        if (showAll) return true;

        // Hide if null, undefined, empty string, 0, or "0"
        if (value === null || value === undefined) return false;
        if (value === "") return false;
        if (value === 0 || value === "0") return false;

        return true;
    });

    return (
        <div className="space-y-4">
            <div className="flex items-center space-x-2 justify-end">
                <Switch id="show-all" checked={showAll} onCheckedChange={setShowAll} />
                <Label htmlFor="show-all">Show all properties</Label>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {visibleProperties.length === 0 ? (
                    <div className="col-span-full text-center text-muted-foreground py-8">
                        No visible properties. Toggle "Show all" to see hidden fields.
                    </div>
                ) : (
                    visibleProperties.map(([key, value]) => (
                        <PropertyItem
                            key={key}
                            label={key}
                            value={value as string}
                            type={type}
                            id={id}
                            propertyKey={key}
                        />
                    ))
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { EditProperty } from "@/components/dashboard/edit-property";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { History } from "lucide-react";
import { getPropertyHistory } from "@/lib/actions";

interface PropertyItemProps {
    label: string;
    value: string | number | null | undefined;
    type: string;
    id: string;
    propertyKey: string;
}

export function PropertyItem({ label, value, type, id, propertyKey }: PropertyItemProps) {
    const [history, setHistory] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [open, setOpen] = useState(false);

    const handleOpenHistory = async () => {
        setOpen(true);
        if (history.length === 0) {
            setLoading(true);
            try {
                const data = await getPropertyHistory(type, id, propertyKey);
                setHistory(data);
            } catch (error) {
                console.error("Failed to fetch history", error);
            } finally {
                setLoading(false);
            }
        }
    };

    return (
        <div className="flex flex-col space-y-1 border p-3 rounded-md relative group">
            <span className="text-sm font-medium text-muted-foreground">{label}</span>
            <div className="flex items-center justify-between gap-2">
                <div className="flex-1 min-w-0">
                    <EditProperty
                        type={type}
                        id={id}
                        propertyKey={propertyKey}
                        value={value}
                    />
                </div>
                <Dialog open={open} onOpenChange={setOpen}>
                    <DialogTrigger asChild>
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity"
                            onClick={handleOpenHistory}
                            title="View History"
                        >
                            <History className="h-4 w-4" />
                        </Button>
                    </DialogTrigger>
                    <DialogContent>
                        <DialogHeader>
                            <DialogTitle>History for {label}</DialogTitle>
                        </DialogHeader>
                        <div className="max-h-[60vh] overflow-y-auto space-y-4">
                            {loading ? (
                                <div className="text-center py-4 text-sm text-muted-foreground">Loading history...</div>
                            ) : history.length === 0 ? (
                                <div className="text-center py-4 text-sm text-muted-foreground">No history available via API.</div>
                            ) : (
                                history.map((item: any, index: number) => (
                                    <div key={index} className="flex flex-col border-b pb-2 last:border-0">
                                        <span className="font-medium text-sm">{item.value}</span>
                                        <span className="text-xs text-muted-foreground">
                                            {new Date(item.timestamp).toLocaleString()}
                                        </span>
                                        {item.sourceType && (
                                            <span className="text-xs text-muted-foreground">Source: {item.sourceType}</span>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </DialogContent>
                </Dialog>
            </div>
        </div>
    );
}

